    "description": "Pre-turn hook: verify an ssh-signed public payload and assert the identity `mike` in the `ssh` namespace. Prints `mike` and exits 0 on a good signature over namespace `mshkn`; prints nothing and exits 1 otherwise.",
    "dockerfile": "FROM mshkn-base\nRUN apt-get update && apt-get install -y jq && rm -rf /var/lib/apt/lists/*\nRUN mkdir -p /verb && printf '%s\\n' 'mike ssh-ed25519 AAAAC3NzaC1lZDI1NTE5AAAAIJkGgH9UztXHrge1ndNT8u286zPYvhCHsN8yrW4tsbk1 mike' > /verb/allowed_signers\nRUN printf '%s\\n' '#!/bin/sh' 'payload=\"${1:-}\"' 'if [ -z \"$payload\" ]; then payload=\"$(cat)\"; fi' 'allowed=\"${ALLOWED:-/verb/allowed_signers}\"' 'd=\"$(mktemp -d)\"' 'msg=\"$(printf \"%s\" \"$payload\" | jq -r \".msg // empty\" 2>/dev/null)\"' 'sig=\"$(printf \"%s\" \"$payload\" | jq -r \".sig // .signature // empty\" 2>/dev/null)\"' 'if [ -z \"$sig\" ] || [ -z \"$msg\" ]; then exit 1; fi' 'printf \"%s\\n\" \"$sig\" > \"$d/sig\"' 'for v in bare nl; do' '  if [ \"$v\" = bare ]; then printf \"%s\" \"$msg\" > \"$d/m\"; else printf \"%s\\n\" \"$msg\" > \"$d/m\"; fi' '  if ssh-keygen -Y verify -f \"$allowed\" -I mike -n mshkn -s \"$d/sig\" < \"$d/m\" >/dev/null 2>&1; then printf \"%s\" mike; exit 0; fi' 'done' 'exit 1' > /verb/hook.sh && chmod +x /verb/hook.sh",
