    "dockerfile": "FROM mshkn-base\nRUN apt-get update && apt-get install -y --no-install-recommends python3 ca-certificates && rm -rf /var/lib/apt/lists/*\nRUN mkdir -p /verb\nRUN printf '%s\\n' 'import sys, re, html, urllib.request, urllib.error' 'def fail(m, c=2):' '    sys.stderr.write(m + \"\\n\")' '    sys.exit(c)' 'url = sys.argv[1] if len(sys.argv) > 1 else \"\"' 'if not url.startswith((\"http://\", \"https://\")):' '    fail(\"error: url must start with http:// or https://\")' 'req = urllib.request.Request(url, headers={\"User-Agent\": \"mshkn-page-title/1\"})' 'try:' '    with urllib.request.urlopen(req, timeout=15) as r:' '        ctype = r.headers.get(\"Content-Type\", \"\")' '        raw = r.read(1048576)' '        final = r.geturl()' '        status = r.status' 'except urllib.error.HTTPError as e:' '    fail(\"error: http status \" + str(e.code))' 'except Exception as e:' '    fail(\"error: fetch failed: \" + str(e)[:200])' 'enc = \"utf-8\"' 'm = re.search(\"charset=([A-Za-z0-9_.:-]+)\", ctype)' 'if m:' '    enc = m.group(1)' 'try:' '    text = raw.decode(enc, \"replace\")' 'except LookupError:' '    text = raw.decode(\"utf-8\", \"replace\")' 't = re.search(\"<title[^>]*>(.*?)</title>\", text, re.I | re.S)' 'if t is None:' '    fail(\"error: no <title> element found (content-type: \" + ctype + \")\", 3)' 'title = re.sub(\"\\\\s+\", \" \", html.unescape(t.group(1))).strip()' 'if title == \"\":' '    fail(\"error: <title> element is empty\", 3)' 'print(title)' 'sys.stderr.write(\"fetched: \" + final + \" status: \" + str(status) + \"\\n\")' > /verb/title.py\nRUN python3 -c \"import py_compile; py_compile.compile('/verb/title.py', doraise=True)\"\n",
